'use strict';
const $ = s => document.querySelector(s);
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',closet:'M9 6a3 3 0 1 1 3 3v2L3 17v3h18v-3l-9-6',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',user:'M20 21v-2a7 7 0 0 0-14 0v2M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',plus:'M12 5v14M5 12h14',arrow:'M5 12h14m-5-5 5 5-5 5',back:'m14 5-7 7 7 7',chevron:'m9 5 7 7-7 7',sun:'M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',lock:'M6 11h12v10H6ZM8 11V7a4 4 0 0 1 8 0v4m-4 4v2',unlock:'M6 11h12v10H6ZM8 11V7a4 4 0 0 1 7.5-2',spark:'m12 3 2.2 6.8L21 12l-6.8 2.2L12 21l-2.2-6.8L3 12l6.8-2.2Z',camera:'M3 7h4l2-3h6l2 3h4v14H3ZM16 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0',check:'m5 12 4 4L19 6',close:'m6 6 12 12M18 6 6 18',undo:'M9 4 4 9l5 5M4 9h10a6 6 0 0 1 0 12',swap:'M4 7h16m-4-4 4 4-4 4M20 17H4m4-4-4 4 4 4',leaf:'M20 3C8 3 3 7 5 15s15 5 15-12ZM5 20 16 9',grid:'M3 3h7v7H3ZM14 3h7v7h-7ZM3 14h7v7H3ZM14 14h7v7h-7Z',image:'M3 3h18v18H3Zm0 13 6-6 6 6 3-3 3 3M16 7h.01',info:'M12 8h.01M12 11v6M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',bookmark:'M6 3h12v18l-6-4-6 4Z'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.spark}"/></svg>`;
const escapeHTML=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const originalItems=[{id:'knit',name:'奶油白针织衫',cat:'上衣',color:'奶油白',x:0,y:0},{id:'pants',name:'炭灰色阔腿裤',cat:'下装',color:'炭灰',x:50,y:0},{id:'sage',name:'鼠尾草绿衬衫',cat:'上衣',color:'鼠尾草绿',x:100,y:0},{id:'blue',name:'浅蓝色棉衬衫',cat:'上衣',color:'浅蓝',x:0,y:100},{id:'shoes',name:'黑色乐福鞋',cat:'鞋履',color:'黑色',x:50,y:100},{id:'bag',name:'巧克力肩包',cat:'配饰',color:'巧克力色',x:100,y:100}];
const defaults=()=>({items:originalItems.map(x=>({...x})),saved:[],prefs:['简约日常','宽松一些'],context:{city:'杭州',day:'今天',scene:'日常通勤',temp:'18–24℃'},newUser:false,reference:false});
let data;try{data={...defaults(),...JSON.parse(localStorage.getItem('wear-prototype-v1')||'null')};}catch{data=defaults();}
let state={page:'home',filter:'全部',select:'pants',top:'knit',locks:['pants'],history:[],wear:'自然垂放',version:1,previewVersion:0,compare:false,previewLook:0,modal:null,savedFilter:'全部',draft:null,feedbackId:null};
let modalReturn=null,toastTimer,loadingTimer;
function persist(){try{localStorage.setItem('wear-prototype-v1',JSON.stringify(data));}catch{toast('本地空间不足，本次修改仅保留到页面关闭');}}
function item(id){return data.items.find(i=>i.id===id)||originalItems.find(i=>i.id===id);}
function art(id,cls=''){const i=item(id);return i?`<div class="item-art ${cls}" role="img" aria-label="${escapeHTML(i.name)}" style="--x:${i.x||0}%;--y:${i.y||0}%">${i.photo?`<img src="${i.photo}" alt="${escapeHTML(i.name)}">`:''}</div>`:'';}
function btn(action,text,cls='primary',attrs=''){return `<button class="${cls}" data-action="${action}" ${attrs}>${text}</button>`;}
const snapshot=()=>({top:state.top,locks:[...state.locks],wear:state.wear,select:state.select,version:state.version});
function edit(change){state.history.push(snapshot());Object.assign(state,change);state.version++;state.previewVersion=0;}
function getPieces(){const selected=item(state.select);const ids=[state.top,selected&&selected.cat==='下装'?selected.id:'pants','shoes'];if(selected&&!ids.includes(selected.id))ids.push(selected.id);return [...new Set(ids)];}
function title(text,sub='',right=''){return `<div class="page-top"><div><h2>${text}</h2>${sub?`<p class="sub">${sub}</p>`:''}</div>${right}</div>`;}
function back(text,to='home',right=''){return `<div class="back-title">${btn('go',icon('back'),'round-button',`data-page="${to}" aria-label="返回"`)}<h2>${text}</h2>${right}</div>`;}
function card(id,mini=false){const i=item(id);return `<button class="${mini?'mini-item':'item-card'}" data-action="detail" data-id="${id}">${art(id)}${mini?`<p>${escapeHTML(i.name)}</p>`:`<h3>${escapeHTML(i.name)}</h3><p>${escapeHTML(i.cat)} / ${i.photo?'本地照片':'演示单品'}</p>`}</button>`;}
function board(top=state.top,small=false){return `<div class="outfit-board">${art(top,'top')}${art('pants','pants')}${art('shoes','shoes')}<span class="board-caption">${small?'':'已录入衣橱的组合'}</span>${small?'':`<span class="lock-badge">${icon('lock')}${escapeHTML(item(state.select)?.name||'基础单品')}</span>`}</div>`;}
function weather(){return `<button class="weather" data-action="context">${icon('sun')}<span><strong>${escapeHTML(data.context.city)} ${escapeHTML(data.context.temp)}　晴间多云</strong><small>${escapeHTML(data.context.day)} · ${escapeHTML(data.context.scene)}　天气为示例</small></span>${icon('chevron')}</button>`;}
function home(){return `<div class="page"><div class="page-top"><div><p class="hello">10月26日，星期一</p><h2>今天，穿点喜欢的。</h2></div>${btn('go','林','round-button avatar','data-page="profile" aria-label="我的资料"')}</div>${weather()}${data.newUser?`<div class="onboarding"><span class="tag">从一件开始就好</span><h3>先认识你喜欢的那件。</h3><p>拍一张照片，其他资料以后慢慢补。<br>不需要先整理完整个衣橱。</p>${btn('go',icon('plus')+'添加第一件衣服','primary','data-page="add"')}</div>`:`<div class="hero"><div class="look-art" style="--look:0" role="img" aria-label="针织衫与阔腿裤的虚构模特穿搭示意"></div><div class="hero-copy"><span class="tiny">今日衣橱灵感</span><h2>熟悉的衣服，<br>新的默契。</h2><p>温柔的针织，利落的线条。<br>把舒服穿进日常。</p></div><span class="hero-tag">虚构模特 · 搭配示意</span></div>${btn('go',icon('spark')+'从一件衣服开始搭配','primary home-cta','data-page="choose"')}<p class="under-note">只用已有的衣服，也能有新鲜感</p>`}<div class="section-head"><h3>${data.newUser?'先看看示例':'衣橱里的老朋友'}</h3>${btn('go','查看衣橱','text-button','data-page="closet"')}</div><div class="mini-grid">${['knit','pants','bag'].map(id=>card(id,true)).join('')}</div><div class="section-head"><h3>不急着买，先好好穿。</h3></div><p class="subtitle">让每一件衣服，多一种可能。</p></div>`;}
function closet(){const list=data.newUser?data.items.filter(i=>i.photo||i.added):data.items;return `<div class="page">${title('我的衣橱',`${list.length} 件已录入 · 慢慢收集，常常喜欢`,btn('go',icon('plus'),'round-button','data-page="add" aria-label="添加衣服"'))}<div class="chips">${['全部','上衣','下装','鞋履','配饰'].map(c=>btn('filter',c,`chip ${state.filter===c?'active':''}`,`data-value="${c}"`)).join('')}</div>${list.length?`<div class="closet-grid">${list.filter(i=>state.filter==='全部'||i.cat===state.filter).map(i=>card(i.id)).join('')}</div><p class="subtle-info">照片先存下来，尺寸和细节用到时再补。</p>`:`<div class="empty">${icon('closet')}<h3>一件，就是好的开始。</h3><p>先添加今天想穿的衣服，<br>不需要一次整理整个衣橱。</p>${btn('go','添加第一件','primary','data-page="add"')}</div>`}</div>`;}
function choose(){const list=data.newUser?data.items.filter(i=>i.added):data.items;return `<div class="page">${back('从哪一件开始？')}<h2>今天，想穿这件。</h2><p class="subtitle">选中一件喜欢的，其他的交给搭配。</p><div class="chooser-grid">${list.map(i=>`<button class="item-card ${state.select===i.id?'selected':''}" data-action="select" data-id="${i.id}" aria-pressed="${state.select===i.id}">${art(i.id)}<h3>${escapeHTML(i.name)}</h3></button>`).join('')}</div>${!list.length?`<div class="notice">还没有录入衣服，先添加一件就好。</div>`:''}<div class="fixed-action">${btn(list.length?'build':'go',list.length?'搭配这件衣服':'添加第一件','primary',list.length?'':'data-page="add"')}<p class="under-note" style="margin-top:9px">选中的单品会保持锁定</p></div></div>`;}
function outfit(){return `<div class="page">${back('为你搭配','choose',state.history.length?btn('undo',icon('undo')+'撤销','text-button'):'')}<span class="tag">${icon('closet')} 来自你的衣橱</span><div class="outfit-title"><h2>${state.top==='sage'?'多一点松弛感。':state.top==='blue'?'清爽，也很利落。':'舒服得刚刚好。'}</h2><p class="subtitle">${escapeHTML(data.context.day)} · ${escapeHTML(data.context.scene)} · ${escapeHTML(data.context.temp)}</p></div>${board()}<div class="reason">${icon('leaf')}<span>${state.top==='sage'?'柔和的绿色让灰色更轻盈，敞开穿也更自在。':'浅色上衣让整体更轻盈，阔腿线条保留舒服的余地。'}<br>晚间降温时，可另选一件外层。</span></div>${getPieces().map(id=>`<div class="piece-row">${art(id)}<div class="piece-text"><strong>${escapeHTML(item(id).name)}</strong><small>${state.locks.includes(id)?'已锁定，替换时保留':'可换成其他喜欢的单品'}</small></div>${btn('lock',icon(state.locks.includes(id)?'lock':'unlock'),`small-button ${state.locks.includes(id)?'locked':''}`,`data-id="${id}" aria-label="${state.locks.includes(id)?'解锁':'锁定'}${item(id).name}"`)}${btn('replace','换一件','small-button',`data-id="${id}"`)}</div>`).join('')}<div class="wearing"><span>穿法 · ${escapeHTML(state.wear)}</span>${btn('wear','调整穿法','text-button')}</div><div class="actions">${btn('preview-start',icon('spark')+'看看上身效果')}${btn('save',icon('bookmark'),'secondary','aria-label="收藏这套搭配"')}</div><p class="under-note" style="margin-top:9px">可以先保存搭配，预览稍后再看</p></div>`;}
function preview(){const current=state.previewVersion===state.version;return `<div class="page">${back('上身预览','outfit')}<span class="tag">${icon('info')} 原型示意 · 非真实试穿</span><div class="segmented">${btn('preview-mode','单套查看',!state.compare?'active':'','data-value="single"')}${btn('preview-mode','两套比较',state.compare?'active':'','data-value="compare"')}</div>${!current?`<div class="empty">${icon('image')}<h3>搭配已调整</h3><p>上一张示意图不代表当前方案。<br>你可以重新体验预览流程。</p>${btn('preview-start','重新预览')}</div>`:state.compare?`<div class="preview-compare">${[0,1].map((v)=>`<div><div class="preview-single"><div class="look-art" style="--look:${v}" role="img" aria-label="${v?'绿色衬衫':'白色针织'}预制示意"></div><span class="demo-label">示例 ${v?'B':'A'}</span></div><p>${v?'换一件，松弛一点':'日常的温柔'}</p></div>`).join('')}</div><div class="notice">同一虚构模特、相近姿态与背景。两套为预制示例，不会随上传照片或穿法变化。</div>`:`<div class="preview-single"><div class="look-art" style="--look:${state.previewLook}" role="img" aria-label="虚构模特预制穿搭示意"></div><span class="demo-label">演示参考人物</span></div><div class="notice">这是预制的视觉示例，尚未接入 AI。不能据此判断你的实际比例、松紧和衣长。</div>`}${btn('save',icon('bookmark')+'保存当前搭配')}<div class="section-head"><span class="subtitle">搭配清单始终保留</span>${btn('go','返回调整','text-button','data-page="outfit"')}</div></div>`;}
function saved(){const list=data.saved.filter(s=>state.savedFilter==='全部'||(state.savedFilter==='穿过且满意'?s.worn&&s.satisfied:s.worn));return `<div class="page">${title('我的搭配','把喜欢的，留给下一次。')}<div class="chips">${['全部','穿过','穿过且满意'].map(c=>btn('saved-filter',c,`chip ${state.savedFilter===c?'active':''}`,`data-value="${c}"`)).join('')}</div>${list.length?list.map(s=>`<article class="saved-card">${board(s.top,true)}<div class="saved-content"><span class="tag">${s.worn?(s.satisfied?'穿过且满意':'已穿过 · 未确认满意'):'已收藏 · 尚未穿过'}</span><h3 style="margin-top:10px">${escapeHTML(s.name)}</h3><p>${escapeHTML(s.scene)} · ${escapeHTML(s.wear)} · ${s.ids.length} 件单品</p><div class="saved-actions">${btn('reuse','再穿这套','secondary',`data-id="${s.id}"`)}${btn('feedback',s.worn?'补充感受':'今天穿了','secondary',`data-id="${s.id}"`)}</div></div></article>`).join(''):`<div class="empty">${icon('bookmark')}<h3>${state.savedFilter==='全部'?'喜欢的搭配，值得留下。':'还没有这样的穿着记录'}</h3><p>${state.savedFilter==='全部'?'搭配完成后保存到这里，<br>下次不用重新开始。':'收藏不等于穿过。<br>真实穿着后，再记录你的感受。'}</p>${btn('go','去搭一套','primary','data-page="choose"')}</div>`}</div>`;}
function profile(){return `<div class="page">${title('我的')}<div class="profile-head"><span class="profile-avatar">林</span><div><h2>做自在的自己。</h2><p>个人资料按需要补充就好</p></div></div><div class="profile-note"><h3>先懂你的喜欢。</h3><p>今天的心情可以不同。临时想穿正式一点，不会改变你的长期偏好。</p></div>${[['prefs','heart','穿衣偏好',data.prefs.join('、')||'未设置'],['reference','user','人物参考',data.reference?'使用演示参考':'尚未准备'],['body','grid','身材资料','按需补充'],['privacy','lock','照片与隐私','仅本地原型']].map(([a,i,t,v])=>btn(a,icon(i)+`<span>${t}<small style="display:block;margin-top:5px">${escapeHTML(v)}</small></span>`+icon('chevron'),'setting-row')).join('')}<p class="subtle-info">本原型不上传照片，不接入账号或模型服务。<br>演示内容只保存在当前浏览器。</p></div>`;}
function add(){return `<div class="page">${back('添加一件衣服','closet')}<p class="step-top">先有照片，其他慢慢来。</p><h2>从这一件开始。</h2><p class="subtitle">不用找尺子，也不用填写一整张表。</p>${state.draft?`<div class="upload-preview">${state.draft.photo?`<div class="item-art"><img src="${state.draft.photo}" alt="待录入的衣服"></div>`:art('blue')}</div><label class="field">给它一个名字<input id="item-name" value="${escapeHTML(state.draft.name)}" maxlength="30"></label><label class="field">确认品类<select id="item-cat">${['上衣','下装','鞋履','配饰'].map(c=>`<option ${c===state.draft.cat?'selected':''}>${c}</option>`).join('')}</select></label><div class="notice">确认照片里是哪一件衣服即可。尺寸、面料和体感都可以以后再补。</div>${btn('add-save','保存到衣橱')}${btn('upload','重新选择照片','text-button')}`:`<button class="upload" data-action="upload" style="width:100%">${icon('camera')}<strong>拍照或从相册选择</strong><small>拍清衣服整体，一张就可以</small></button>${btn('demo-upload','先用示例体验','secondary','style="width:100%"')}<p class="subtle-info">照片仅在本地预览，不会上传。<br>本原型不自动识别品类，请手动确认。</p>`}<input class="file-input" id="photo-input" type="file" accept="image/*"></div>`;}
const views={home,closet,choose,outfit,preview,saved,profile,add};
function render(){const oldFocus=document.activeElement;$('#app').innerHTML=views[state.page]();const active=['choose','outfit','preview','add'].includes(state.page)?(state.page==='add'?'closet':'home'):state.page;$('#bottom-nav').innerHTML=[['home','home','今天'],['closet','closet','衣橱'],['saved','bookmark','搭配'],['profile','user','我的']].map(([p,i,t])=>btn('go',icon(i)+t,`nav-item ${active===p?'active':''}`,`data-page="${p}" ${active===p?'aria-current="page"':''}`)).join('');$('#studio-nav').innerHTML=[['home','今日灵感'],['closet','我的衣橱'],['choose','从一件开始'],['outfit','搭配与调整'],['preview','上身预览'],['saved','喜欢的搭配'],['profile','个人偏好']].map(([p,t])=>btn('go',`<span></span>${t}`,`rail-link ${state.page===p?'active':''}`,`data-page="${p}"`)).join('');const notes={home:['少一点纠结，<br>多一点喜欢。','用一件想穿的衣服开启搭配。不必先整理完整个衣橱。'],closet:['每一件，<br>都有它的位置。','先保存照片，用到时再补充。把入库的负担分散到日常。'],outfit:['保留喜欢的，<br>只换这一件。','锁定、局部替换与撤销，让推荐成为可以一起调整的方案。'],preview:['看见差异，<br>再做选择。','比较尽量保持相同条件。示意图与真实试穿之间，有明确边界。'],saved:['穿过的喜欢，<br>值得再一次。','收藏、穿过和满意分别记录。让真实体验成为下次的参考。']};const n=notes[state.page]||notes.home;$('#note-title').innerHTML=n[0];$('#note-text').textContent=n[1];}
function go(page){if(!views[page])return;closeModal(false);state.page=page;render();$('#app').scrollTop=0;history.replaceState(null,'','#'+page);}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600);}
function openModal(type,html){modalReturn=document.activeElement;state.modal=type;$('#modal-root').innerHTML=`<div class="modal-overlay" data-dismiss="true"><section class="sheet" role="dialog" aria-modal="true" aria-label="${type}"><div class="sheet-handle"></div>${html}</section></div>`;setTimeout(()=>$('#modal-root button, #modal-root input, #modal-root select')?.focus(),20);}
function closeModal(restore=true){state.modal=null;$('#modal-root').innerHTML='';if(restore&&modalReturn?.isConnected)modalReturn.focus();}
function sheetHead(t){return `<div class="sheet-head"><h2>${t}</h2>${btn('close',icon('close'),'','aria-label="关闭弹层"')}</div>`;}
function openContext(){openModal('调整当天场景',`${sheetHead('今天，要去哪里？')}<p class="description">只调整本次搭配，不改变长期偏好。</p><label class="field">地点<input id="context-city" maxlength="20" value="${escapeHTML(data.context.city)}"></label><label class="field">日期<select id="context-day"><option ${data.context.day==='今天'?'selected':''}>今天</option><option ${data.context.day==='明天'?'selected':''}>明天</option></select></label><label class="field">场景<select id="context-scene">${['日常通勤','周末散步','朋友见面','全天户外'].map(c=>`<option ${data.context.scene===c?'selected':''}>${c}</option>`).join('')}</select></label><div class="notice">天气为固定演示值 18–24℃，不随地点改变，也不是实时预报。</div>${btn('context-save','用于这次搭配')}`);}
function detail(id){const i=item(id);openModal('衣服详情',`${sheetHead(i.name)}<div class="large-art">${art(id)}</div><span class="tag">可以用于基础搭配</span><div class="detail-list"><span><small>品类</small>${escapeHTML(i.cat)}</span><span><small>颜色</small>${escapeHTML(i.color||'尚未确认')}</span><span><small>来源</small>${i.photo?'你选择的本地照片':'演示资料'}</span><span><small>实测尺寸</small>未填写</span></div><p class="description">需要判断衣长或松紧时，再补相关尺寸。现在也可以先看看怎么搭。</p>${btn('use-item','围绕这件搭配','primary',`data-id="${id}"`)}`);}
function replace(id){if(state.locks.includes(id)){toast('这件已锁定。解锁后才能替换。');return;}const i=item(id);const choices=data.items.filter(x=>x.cat===i.cat&&x.id!==id);openModal('替换一件单品',`${sheetHead('只换这一件。')}<p class="description">其他锁定单品保持不变。</p>${choices.length?`<div class="chooser-grid">${choices.map(x=>`<button class="item-card" data-action="apply-replace" data-id="${x.id}" data-old="${id}">${art(x.id)}<h3>${escapeHTML(x.name)}</h3></button>`).join('')}</div>`:`<div class="notice">已录入衣橱里暂时没有其他${i.cat}。这不代表你没有，可以再添加一件。</div>${btn('go','添加我已有的','primary','data-page="add"')}`}${btn('close','保留原来的搭配','text-button')}`);}
function build(){if(!item(state.select))return;state.top=item(state.select).cat==='上衣'?state.select:'knit';state.locks=[state.select];state.history=[];state.version++;state.previewVersion=0;go('outfit');if(data.newUser)toast('当前组合包含示例单品，仅供体验流程');}
function startPreview(){if(!data.reference){openModal('准备人物参考',`${sheetHead('先准备人物参考。')}<p class="description">真实预览需要你的照片。本原型不收集人物照片，可以使用虚构人物体验流程。</p><div class="notice">两套预制示意只展示界面，不会根据你的衣服、身材或穿法重新生成。</div>${btn('reference-use','使用演示人物，继续')}${btn('go','先看搭配清单','text-button','data-page="outfit"')}`);return;}openModal('预览演示',`${sheetHead('正在准备示意')}<div class="loading"><div class="spinner"></div><h3>让搭配更直观一点。</h3><p>正在模拟生成等待状态，未调用 AI 服务。</p></div>${btn('preview-fail','体验失败状态','text-button')}`);clearTimeout(loadingTimer);loadingTimer=setTimeout(()=>{if(state.modal!=='预览演示')return;state.previewVersion=state.version;state.previewLook=state.top==='sage'?1:0;go('preview');},900);}
function save(){const ids=getPieces();const existing=data.saved.find(s=>JSON.stringify(s.ids)===JSON.stringify(ids)&&s.wear===state.wear);if(existing){toast('这套已经收藏，可以在“搭配”里找到');return;}data.saved.unshift({id:Date.now().toString(),name:state.top==='sage'?'绿意里的松弛日常':'轻盈日常',top:state.top,ids,select:state.select,wear:state.wear,scene:data.context.scene,worn:false,satisfied:false});persist();toast('已收藏到“我的搭配”，尚未标记穿过');}
function feedback(id){state.feedbackId=id;openModal('记录穿着感受',`${sheetHead('今天穿了，感觉如何？')}<p class="description">选一个感受就好，也可以先只记录穿过。</p>${btn('feedback-save','舒服，也喜欢 '+icon('check'),'choice','data-value="happy"')}${btn('feedback-save','有一点不合适','choice','data-value="unhappy"')}${btn('feedback-save','先只记录穿过','text-button','data-value="skip"')}`);}
function preferences(){openModal('长期穿衣偏好',`${sheetHead('穿得像自己。')}<p class="description">这是长期偏好。今天想换个风格，可以在当次搭配中调整。</p>${['简约日常','宽松一些','利落修身','柔和配色','不穿高跟鞋'].map(p=>btn('pref-toggle',p+(data.prefs.includes(p)?icon('check'):''),`choice ${data.prefs.includes(p)?'selected':''}`,`data-value="${p}" aria-pressed="${data.prefs.includes(p)}"`)).join('')}${btn('prefs-done','完成','primary','style="margin-top:15px"')}`);}
document.addEventListener('click',e=>{if(e.target.classList.contains('modal-overlay')){closeModal();return;}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id,v=b.dataset.value;
 switch(a){
 case 'go':go(b.dataset.page);break;
 case 'reset':openModal('重置演示',`${sheetHead('重新体验？')}<p class="description">只清空当前浏览器中的本原型收藏、偏好与照片，项目文件不会改变。</p>${btn('reset-confirm','恢复初始示例')}${btn('first-run','体验首次空衣橱','secondary','style="width:100%;margin-top:10px"')}${btn('close','取消','text-button')}`);break;
 case 'reset-confirm':data=defaults();state.draft=null;persist();go('home');toast('已恢复示例数据');break;
 case 'first-run':data=defaults();data.newUser=true;state.draft=null;persist();go('home');break;
 case 'filter':state.filter=v;render();break;
 case 'saved-filter':state.savedFilter=v;render();break;
 case 'select':state.select=id;render();break;
 case 'detail':detail(id);break;
 case 'close':closeModal();break;
 case 'context':openContext();break;
 case 'context-save':data.context={...data.context,city:$('#context-city').value.trim()||'未设置地点',day:$('#context-day').value,scene:$('#context-scene').value};persist();closeModal();render();toast('已更新当次场景；天气仍为演示值');break;
 case 'build':build();break;
 case 'use-item':state.select=id;build();break;
 case 'lock':state.locks=state.locks.includes(id)?state.locks.filter(x=>x!==id):[...state.locks,id];render();break;
 case 'replace':replace(id);break;
 case 'apply-replace':if(state.locks.includes(b.dataset.old)){toast('这件单品已锁定');break;}if(item(id).cat==='上衣')edit({top:id});else if(b.dataset.old===state.select)edit({select:id});else {toast('这个品类的替换尚未纳入原型');break;}closeModal();render();toast('已替换一件，其他锁定单品保持不变');break;
 case 'undo':if(state.history.length){Object.assign(state,state.history.pop());state.previewVersion=0;render();toast('已恢复上一版搭配');}break;
 case 'wear':openModal('调整穿法',`${sheetHead('小小调整，不同感觉。')}<p class="description">穿法会保存到当前方案。预制示意图不会随穿法变化。</p>${['自然垂放','前侧塞衣角','外层敞开穿'].map(w=>btn('wear-set',w+(w===state.wear?icon('check'):''),`choice ${w===state.wear?'selected':''}`,`data-value="${w}"`)).join('')}`);break;
 case 'wear-set':edit({wear:v});closeModal();render();toast('已更新穿法，预览状态已重置');break;
 case 'preview-start':startPreview();break;
 case 'reference-use':data.reference=true;persist();closeModal();startPreview();break;
 case 'preview-fail':clearTimeout(loadingTimer);openModal('预览失败示例',`${sheetHead('这次预览没有完成。')}<p class="description">这是原型的模拟失败状态。搭配清单和修改都还在，可以重试，或稍后再看。</p>${btn('preview-start','重新尝试')}${btn('go','回到搭配清单','text-button','data-page="outfit"')}`);break;
 case 'preview-mode':state.compare=v==='compare';render();break;
 case 'save':save();break;
 case 'reuse':{const s=data.saved.find(x=>x.id===id);state.top=s.top;state.select=s.select||'pants';state.locks=[state.select];state.wear=s.wear;state.history=[];state.version++;state.previewVersion=0;go('outfit');toast('已复用搭配，请确认今天的场景与单品状态');break;}
 case 'feedback':feedback(id);break;
 case 'feedback-save':{const s=data.saved.find(x=>x.id===state.feedbackId);if(s){s.worn=true;s.satisfied=v==='happy';s.feedback=v;persist();}closeModal();render();toast(v==='happy'?'已记录：穿过且满意':v==='skip'?'已记录穿过，满意情况仍未知':'已记录穿着感受');break;}
 case 'prefs':preferences();break;
 case 'pref-toggle':data.prefs=data.prefs.includes(v)?data.prefs.filter(p=>p!==v):[...data.prefs,v];persist();preferences();break;
 case 'prefs-done':closeModal();render();toast('长期偏好已保存');break;
 case 'reference':openModal('人物参考',`${sheetHead('你的参考，由你决定。')}<p class="description">原型只使用虚构模特，不需要上传你的脸部或身体照片。</p>${btn('reference-toggle',data.reference?'移除演示参考':'使用演示参考')}`);break;
 case 'reference-toggle':data.reference=!data.reference;persist();state.previewVersion=0;closeModal();render();toast('人物参考状态已更新');break;
 case 'body':openModal('身材资料',`${sheetHead('用到时，再补充。')}<p class="description">衣橱录入不要求身高、体重或围度。本原型未接入合身判断，不收集这些数据。</p><div class="notice">真实功能会在判断对应部位时说明需要什么资料，照片估计不会冒充实测。</div>${btn('close','知道了')}`);break;
 case 'privacy':openModal('照片与隐私',`${sheetHead('照片留在你的浏览器。')}<p class="description">所选图片仅用于本地预览，不上传服务器。移除演示数据可以清除本原型存储的照片、收藏和偏好。</p>${btn('reset','管理演示数据','secondary','style="width:100%"')}${btn('close','返回','text-button')}`);break;
 case 'upload':$('#photo-input').click();break;
 case 'demo-upload':state.draft={name:'浅蓝色棉衬衫',cat:'上衣',x:0,y:100};render();break;
 case 'add-save':{const name=$('#item-name').value.trim();if(!name){toast('请给这件衣服一个名字');$('#item-name').focus();break;}const newItem={...state.draft,id:'local-'+Date.now(),name,cat:$('#item-cat').value,added:true};data.items.push(newItem);state.draft=null;persist();go('closet');toast('已入库，尺寸和细节以后再补');break;}
 }
});
document.addEventListener('change',e=>{if(e.target.id!=='photo-input')return;const f=e.target.files?.[0];if(!f)return;if(!f.type.startsWith('image/')){toast('请选择图片文件');return;}const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{const canvas=document.createElement('canvas');const scale=Math.min(1,900/Math.max(img.width,img.height));canvas.width=img.width*scale;canvas.height=img.height*scale;canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);state.draft={name:'我的新衣服',cat:'上衣',photo:canvas.toDataURL('image/jpeg',.82)};render();};img.onerror=()=>toast('无法读取这张图片，请选择 JPEG 或 PNG');img.src=reader.result;};reader.readAsDataURL(f);});
document.addEventListener('keydown',e=>{if(!state.modal)return;if(e.key==='Escape'){closeModal();return;}if(e.key==='Tab'){const els=[...document.querySelectorAll('.sheet button:not(:disabled),.sheet input,.sheet select')];const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('hashchange',()=>{const page=location.hash.slice(1);if(views[page])go(page);});
go(views[location.hash.slice(1)]?location.hash.slice(1):'home');
